/**
 * Global State Management
 */
let estado = {};

// Función de inicialización del estado (si se necesita más estructura)
function initializeState() {
    // Inicializa el estado con un conjunto mínimo si no existe o solo para asegurar la estructura.
    if (!estado.A1) {
        estado = {};
    }
}

// Carga los datos desde el localStorage al iniciar la app
function cargar() {
    const storedState = localStorage.getItem('spreadsheetState');
    if (storedState) {
        try {
            estado = JSON.parse(storedState);
        } catch (e) {
            console.error("Error parsing state from local storage:", e);
            // Si falla el parseo, mantenemos el estado actual o lo reiniciamos si es necesario.
        }
    } else {
        // Si no hay nada guardado, inicializamos un estado vacío.
        estado = {};
    }
}

// Guarda el estado actual en el localStorage
function guardar() {
    localStorage.setItem('spreadsheetState', JSON.stringify(estado));
}

/**
 * State Logic and Updates
 */

// Actualiza el estado interno con el nuevo valor de la celda.
function updateCellState(column, row, value) {
    const key = `${column}${row}`;
    estado[key] = value;
}

// Obtiene las coordenadas (columna y fila) a partir de un elemento DOM dado.
function getCoordsFromElement(element) {
    const col = element.getAttribute('data-col');
    const row = element.getAttribute('data-row');
    return { column: col, row: row };
}

// Maneja la lógica cuando una celda pierde el foco (blur o Enter).
function handleCellBlur(cellElement) {
    const col = cellElement.getAttribute('data-col');
    const row = cellElement.getAttribute('data-row');
    let value = cellElement.innerText.trim();

    // Si el valor está vacío, lo forzamos a cadena vacía en lugar de null.
    if (value === "") {
        value = "";
    }

    updateCellState(col, row, value);
    guardar();
    render();
}


/**
 * Rendering and UI Control
 */

// Redibuja toda la hoja de cálculo basándose en el estado.
function render() {
    const cellGrid = document.getElementById('cell-grid');
    if (!cellGrid) return;

    // 1. Iterar sobre todas las celdas (20 filas, 10 columnas)
    for (let r = 1; r <= 20; r++) {
        for (let c = 0; c < 10; c++) {
            const colLetter = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'][c];
            const key = `${colLetter}${r}`;
            const value = estado[key] || "";

            // 2. Encontrar el elemento DOM correspondiente (usando data attributes)
            const cellElement = document.querySelector(`[data-col="${colLetter}"][data-row="${r}"]`);

            if (cellElement) {
                // 3. Protección de foco: Si esta celda es el elemento activo, NO redibujamos su contenido 
                // para que no se pierda lo que el usuario está escribiendo.
                if (document.activeElement === cellElement) {
                    continue;
                }

                // 4. Actualizar el contenido visible con el valor del estado.
                cellElement.innerText = value;
            }
        }
    }
}

// Conecta los listeners de eventos y prepara la UI.
function conectar() {
    document.getElementById('spreadsheet').addEventListener('click', (e) => {
        if (e.target.classList.contains('cell')) {
            // Cuando se hace clic en cualquier celda, la hacemos editable y ponemos foco.
            const cell = e.target;
            cell.setAttribute('contenteditable', 'true');
            cell.focus();
        }
    });

    document.getElementById('spreadsheet').addEventListener('blur', (e) => {
        // Cuando se pierde el foco de cualquier elemento, guardamos el estado si es una celda.
        if (e.target.classList.contains('cell')) {
            handleCellBlur(e.target);
        }
    });

    document.getElementById('spreadsheet').addEventListener('keydown', (e) => {
        // Capturamos la tecla Enter para guardar sin perder foco de manera abrupta.
        if (e.target.classList.contains('cell') && e.key === 'Enter') {
            e.preventDefault(); // Prevenir salto de línea si el navegador lo hace
            handleCellBlur(e.target);
        }
    });

    // Inicializar estado, cargar datos y dibujar la interfaz.
    initializeState();
    cargar();
    render();
}

// Función que arranca la aplicación (llamada por el harness)
function arrancar() {
    conectar();
}
