### FUNCION: calculateFormula
```javascript
/** 
 * Evalúa una fórmula de estilo Excel si empieza con '='.
 * @param {string} value - El valor actual (puede ser una fórmula).
 * @returns {string} El resultado calculado como string, o el valor original si no es una fórmula válida.
 */
function calculateFormula(value) {
    if (!value || !String(value).startsWith('=')) {
        return value;
    }

    let formula = String(value);
    let expression = formula.substring(1).trim(); // Eliminar '=' inicial

    // 1. Manejo de SUMA (Rango o Lista)
    if (expression.toUpperCase().startsWith("SUMA")) {
        const match = expression.match(/SUMA\((.*)\)/i);
        if (!match) return formula;
        let content = match[1];

        // A. RANGO: Detectar formato A1:B2 (Asumimos un rango simple, vertical o horizontal, para este fix).
        if (content.includes(':')) {
            const [startRef, endRef] = content.split(':').map(s => s.trim().toUpperCase());

            // Intento de detección básica de rango vertical A1:A3
            const startCol = startRef.match(/[A-Z]/);
            const endCol = endRef.match(/[A-Z]/);

            if (startCol && endCol && startCol[0] === endCol[0]) { // Mismo columna, rango vertical
                let minRow = Math.min(parseInt(startRef.match(/\d+/)[0]) || 1, parseInt(endRef.match(/\d+/)[0]) || 1);
                let maxRow = Math.max(parseInt(startRef.match(/\d+/)[0]) || 1, parseInt(endRef.match(/\d+/)[0]) || 1);

                let sum = 0;
                for (let r = minRow; r <= maxRow; r++) {
                    const key = `${startCol[0]}${r}`;
                    const valueState = estado[key] || '0';
                    sum += parseFloat(valueState) || 0;
                }
                return sum.toString();
            }
        }

        // B. LISTA: Detectar formato A1;B2;C3
        if (content.includes(';') && !content.includes(':')) {
            const refs = content.split(';').map(s => s.trim().toUpperCase());
            let sum = 0;
            for (const ref of refs) {
                // Solo procesamos referencias válidas como A1, B2 etc.
                if (ref.match(/^[A-Z]+\d+$/)) {
                    const key = ref;
                    const valueState = estado[key] || '0';
                    sum += parseFloat(valueState) || 0;
                }
            }
            return sum.toString();
        }

        // Si falló el cálculo de SUMA, devolvemos la fórmula original
        return formula;
    }


    // 2. Manejo de Operaciones Aritméticas (Ej: =A1-B1)
    try {
        let expressionString = expression;

        // Encontrar todas las referencias tipo "LETRA + NÚMERO" en la fórmula
        const keysInFormula = [...new Set(expressionString.match(/[A-Z]+\d+/g))];

        for (const key of keysInFormula) {
            let value = parseFloat(estado[key]) || 0;
            // Reemplazar referencias de celda por sus valores numéricos actuales en la expresión matemática
            // Usamos Regex para asegurar que solo reemplazamos referencias completas y no subcadenas.
            const regex = new RegExp(`\\b${key}\\b`, 'g');
            expressionString = expressionString.replace(regex, value);
        }

        // Evaluar la expresión matemática final (ej: 2 + 3)
        return (eval(expressionString)).toString();

    } catch (e) {
