            const segments = rangeContent.split(/,\s*|\;\s*/).filter(s => s);

            for (const segment of segments) {
                let startMatch = segment.match(/([A-Z]+)\s*[:\s]*([1-9]\d*)/i);
                if (!startMatch) continue;

                let col = startMatch[1].toUpperCase();
                let row = parseInt(startMatch[2], 10);

                // Verificar si es un rango (ej: A1:A3)
