                if (endMatch) {
                    let startCol = endMatch[1].toUpperCase();
                    let startRow = parseInt(endMatch[2], 10);
                    let endCol = endMatch[3].toUpperCase();
                    let endRow = parseInt(endMatch[4], 10);

                    // Recorrer el rango
                    for (let r = startRow; r <= endRow; r++) {
                        for (let cCode = startCol.charCodeAt(0) - 'A'.charCodeAt(0); cCode <= endCol.charCodeAt(0) - 'A'.charCodeAt(0); cCode++) {
                            const currentColLetter = String.fromCharCode('A'.charCodeAt(0) + cCode);
                            values.push(`${currentColLetter}${r}`);
                        }
                    }

                } else if (startMatch[1] && startMatch[2]) {
                     // Celda suelta A1 o B3
                    values.push(`${col}${row}`);
                }
            }

            let sum = 0;
            for (const key of values) {
                const value = estado[key];
                if (value !== undefined && value !== "") {
                    // Intentar convertir a número, si falla, usar el valor como string (aunque esto es un error de fórmula)
                    sum += parseFloat(value);
                } else {
                    // Si la celda no existe o está vacía, ignorarla para la suma.
                }
            }
            return sum.toFixed(2).replace(/\.?0+$/, ""); // Formato sin decimales si es entero
        }

        // 2. Manejar Operaciones Aritméticas simples (A1-B1, A1*B1, etc.)
        // Esto requiere evaluar la expresión matemática usando los valores actuales del estado.

        // Creamos un entorno de ejecución donde las referencias de celda se sustituyen por sus valores numéricos/cadenas.
        let expression = content;

        // Expresión regular para encontrar referencias de celdas (ej: A1, B2)
        const cellRefRegex = /([A-Z]+\d+)/g; 

        // Sustituir todas las referencias de celda por sus valores actuales en el estado.
        expression = expression.replace(cellRefRegex, (match) => {
            const value = estado[match];
            if (value === undefined || value === "") return "0"; // Si la celda no existe o está vacía, tratamos como 0 para evitar NaN.
            // Intentar usar el valor numérico si es posible, sino, dejarlo como cadena.
            return isNaN(parseFloat(value)) ? `"${value}"` : value; 
        });

        try {
             // Usar eval() con precaución, ya que solo estamos evaluando una expresión controlada
