/**
 * Evalúa una fórmula de estilo Excel almacenada en el estado.
 * @param {string} formulaString - La cadena que contiene la fórmula (debe empezar con '=').
 * @returns {number|string} El resultado numérico o la cadena original si falla la evaluación.
 */
function evaluateFormula(formulaString) {
    if (!formulaString || !formulaString.startsWith('=')) {
        return formulaString;
    }

    // 1. Pre-procesar: Eliminar el signo '=' inicial para facilitar el parsing.
    let expression = formulaString.substring(1).trim();

    // 2. Manejar SUMA (y otras funciones de suma)
    const sumMatch = expression.match(/SUMA\s*\(([^)]+)\)/i);
    if (sumMatch) {
        const content = sumMatch[1]; // Contenido dentro de los paréntesis
        let valuesToSum = [];

        // Detectar si es un rango (Ej: A1:A3) o celdas sueltas (Ej: A1;B2)
        if (content.includes(':')) {
            // Rango detectado: Procesar columna por fila
            const [colRange, rowEnd] = content.split(':');
            const col = colRange.trim();
            let sum = 0;
            for (let r = parseInt(rowEnd); r <= Math.min(20, parseInt(rowEnd)); r++) { // Ajuste para el rango de filas
                // En lugar de iterar hasta rowEnd, necesitamos un manejo robusto de la columna y las filas.
                // Simplificaremos: asumimos que si hay un rango A1:A3, queremos sumar todas las celdas en esa columna entre esas filas.

                let startRow = parseInt(colRange.replace(/[A-Z]/g, '')); // Intenta extraer el número de inicio (puede fallar)
                if (!startRow || isNaN(parseInt(colRange[colRange.length - 1]))) {
                    // Si no se puede determinar la fila inicial por la letra, asumimos que es solo una columna y procesamos las filas visibles en esa columna.
                    let r = 1;
                    while (r <= 20) {
                         const key = `${col}${r}`;
                         if (estado[key] !== undefined && estado[key] !== "") {
                            sum += parseFloat(estado[key]) || 0;
                        }
                        r++;
                    }
                    return sum.toFixed(2);
                }


            }

            // Reimplementación de Suma de Rango simple (A1:A3)
            const colChar = colRange.match(/[A-Z]/g)?.[0]; // Columna, ej A
            let startRowNum = parseInt(colRange.slice(-1)); // Fila inicio, ej 1
            let endRowNum = parseInt(rowEnd.slice(-1));     // Fila fin, ej 3

            if (colChar && !isNaN(startRowNum) && !isNaN(endRowNum)) {
                let sum = 0;
                for (let r = startRowNum; r <= endRowNum; r++) {
                    const key = `${colChar}${r}`;
                    const value = estado[key];
                    if (value !== undefined) {
                        sum += parseFloat(value) || 0;
                    }
                }
                return sum.toFixed(2);
            }


        } else if (content.includes(';') || content.match(/^[A-Z]\d+$/)) {
             // Celdas sueltas detectadas: A1;B2 o solo una celda A1
            const cells = content.split(';');
            let sum = 0;
            for (const cellRef of cells) {
                const key = cellRef.trim();
                if (estado[key] !== undefined && estado[key] !== "") {
                    sum += parseFloat(estado[key]) || 0;
                }
            }
            return sum.toFixed(2);

        } else {
             // Si el rango es inválido o no se puede procesar, devolver un error o la fórmula original.
            return "Error de Rango";
        }
    }


    // 3. Manejar Operadores Aritméticos (Ej: =A1-B2*C3)
    try {
        // Reemplazar referencias de celda como 'A1' con sus valores reales del estado,
        // asegurando que las operaciones matemáticas funcionen en JavaScript.
        let jsExpression = expression;

        // Expresión regular para encontrar patrones de coordenadas (Ej: A1, J20)
        jsExpression = jsExpression.replace(/([A-Z]+[1-9]\d*)/g, (match) => {
            const key = match.toUpperCase();
            const value = estado[key];
            // Si el valor existe en el estado y es numérico, lo usamos; si no, asumimos 0 para la operación matemática.
            return (value !== undefined && isFinite(parseFloat(value))) ? value : 0;
        });

        // Evaluar la expresión JS resultante
        const result = eval(jsExpression);
        if (isFinite(result)) {
             return parseFloat(result).toFixed(2);
        } else {
             return "Error de Cálculo";
        }

    } catch (e) {
        console.error("Error evaluating formula:", e);
        // Si falla la evaluación, devolvemos el valor original o un mensaje de error.
        return "Fórmula Inválida";
    }
}
