/**
 * Evalúa una fórmula de hoja de cálculo usando el estado global.
 * Asume que las referencias son B1, C2 etc., y solo soporta operaciones básicas (+, -, *, /).
 * @param {string} formula - La cadena de la fórmula (debe empezar con '=').
 * @returns {string} El resultado calculado como string, o la fórmula original si falla.
 */
function evaluateFormula(formula) {
    if (!formula || typeof formula !== 'string' || !formula.startsWith('=')) {
        return formula; // No es una fórmula
    }

    let formulaStr = formula.trim();
    // 1. Remover el signo '=' inicial
    formulaStr = formulaStr.substring(1); 

    // Regex para encontrar referencias de celdas (ej: A1, B20)
    const refRegex = /([A-Z]+\d+)/g; 

    let resolvedFormula = formulaStr.replace(refRegex, (match) => {
        // Reemplazamos la referencia 'B1' con su valor actual en el estado: (estado['B1'])
        const key = match;
        const value = estado[key];
        if (value === undefined) return '0'; // Si no existe, lo tratamos como 0 para evitar NaN
        return `(${value})`;
    });

    try {
        // Usamos eval() porque es la forma más directa de ejecutar operaciones matemáticas complejas en JavaScript.
        // Esto debe hacerse con precaución, pero es necesario para resolver el requerimiento del ejercicio.
        const result = eval(resolvedFormula);
        return String(result); 
    } catch (e) {
        // Si hay un error de cálculo (ej: división por cero), devolvemos la fórmula original.
        console.error("Error evaluando fórmula:", e);
        return formula; 
    }
}
