### FUNCION: evaluateFormula
```js
/** 
 * Evalúa una fórmula de hoja de cálculo basándose en el estado actual.
 * Solo soporta sumas simples con referencias de celda (e.g., "=A1+B2").
 * @param {string} formula - La cadena de la fórmula que comienza con '='.
 * @returns {string} El resultado calculado como string, o la fórmula original si falla.
 */
function evaluateFormula(formula) {
    if (!formula || typeof formula !== 'string' || !formula.startsWith('=')) return null;

    // 1. Limpiar el signo '=' inicial
    let expression = formula.substring(1).trim(); 

    // 2. Regex para encontrar referencias de celda (Ej: A1, J20)
    const cellRegex = /([A-Z]+[0-9])/g;

    // 3. Reemplazar las referencias de celda con sus valores numéricos actuales del estado
    expression = expression.replace(cellRegex, (match) => {
        let valueStr = estado[match] || "0"; 
        let numValue = parseFloat(valueStr);
        // Si el valor no es un número válido o la celda no existe en estado, tratamos como 0.
        return isNaN(numValue) ? '0' : numValue;
    });

    try {
        // Usamos new Function para evaluar la expresión matemática de forma segura dentro del scope JS.
        const result = new Function('return ' + expression)();
        // Devolvemos el resultado como string, ya que todo estado es string.
        return String(result);
    } catch (e) {
        console.error("Error al evaluar fórmula:", e);
        // Si hay un error de evaluación, devolvemos una cadena de error o la fórmula original.
        return formula; 
    }
}
