### FUNCION: updateCellState
```js
function updateCellState(column, row, value) {
    const key = `${column}${row}`;
    let newValue = String(value).trim();

    // 1. Actualizar el estado con el valor de entrada (ya sea dato o fórmula)
    estado[key] = newValue;

    // 2. Iniciar la cascada de recalculaciones: revisar todas las fórmulas que dependan de esta actualización.
    for (const checkKey in estado) {
        if (!estado.hasOwnProperty(checkKey)) continue;

        let currentValue = estado[checkKey];

        // Si el contenido es una fórmula Y NO estamos actualizando la propia celda que está siendo revisada, 
        // y si la clave de la celda actualizada (key) está referenciada en esta fórmula.
        if (typeof currentValue === 'string' && currentValue.startsWith('=') && checkKey !== key) {
            // Nota: Para simplificar la detección de dependencias sin un grafo completo, 
            // simplemente recalculamos TODAS las fórmulas al cambiar CUALQUIER valor, lo cual es más lento pero funcional para el requisito.

             let calculatedValue = evaluateFormula(currentValue); 

             // Si el cálculo resultó en un cambio significativo (no es igual a lo que está guardado), actualizamos el estado con el resultado.
             if (calculatedValue && calculatedValue !== estado[checkKey]) {
                 estado[checkKey] = calculatedValue; // Actualiza el estado con el valor calculado
             }
        }
    }
}
