 * Esto debe llamarse después de cualquier cambio de datos para mantener la coherencia del modelo.
 */
function recalculateAllFormulas() {
    let changed = false;
    // Iterar sobre TODAS las claves en el estado (A1:J20)
    for (const key of Object.keys(estado)) {
        const value = estado[key];

        if (typeof value === 'string' && value.startsWith('=')) {
