    expression = expression.replace(cellRegex, (match) => {
        const value = getCellValue(match);
        // Si la referencia es vacía, se trata como '0' para evitar errores matemáticos.
        return value === '' ? '0' : value;
    });

    try {
        // Paso 2: Evaluar la expresión matemática resultante usando Function constructor (más seguro que eval()).
        let result = Function('return ' + expression)(); 
        // Limpiamos el resultado para mantenerlo como string y asegurar precisión.
        return String(parseFloat(result.toString()));
    } catch (e) {
        console.error("Error evaluando fórmula:", e);
        return "#ERROR!"; // Devolver un indicador de error si falla la evaluación
    }
}

/** Obtiene la letra de la columna a partir de una clave A1. */
function getColFromKey(key) {
    const match = key.match(/^([A-Z]+)/);
    return match ? match[1] : '';
}

/** Obtiene el número de fila a partir de una clave A1. */
