            // Si el valor calculado es diferente al valor almacenado, actualizamos el estado.
            if (String(estado[key]) !== calculatedValue) {
                const col = getColFromKey(key);
                const row = getRowNum(key);
                updateCellState(col, row, calculatedValue);
                changed = true;
            }
        }
    }
    return changed;
