```js
function conectar() {
    const cellGrid = document.getElementById('cell-grid');

    if (!cellGrid) return;

    /** 
     * Maneja el guardado de contenido cuando el usuario termina de editar o presiona Enter.
     * @param {Event} event - El evento DOM (focusout o keydown).
     */
    const handleCellEditEnd = function(event) {
        let target = event.target;

        // 1. Asegurarse de que el objetivo es realmente una celda editable dentro del grid.
        if (!target || !target.classList.contains('editable')) return;

        // 2. Capturar coordenadas y nuevo valor
        const { col, row } = getCoordsFromElement(target);
        let newValue = '';

        // Si es un keydown de Enter, el evento se dispara en el target.
        if (event.type === 'keydown' && event.key === 'Enter') {
            // El valor ya está en innerText del target si lo hemos usado como campo de texto
             newValue = target.innerText; 
            // Prevenir el comportamiento por defecto de Enter para que no pase a la siguiente celda automáticamente si no es necesario
            event.preventDefault(); 

        } else if (event.type === 'focusout') {
            // Capturar el valor final al perder el foco
            newValue = target.innerText;
        } else {
             return; // No procesar otros eventos
        }


        // 3. Lógica: Actualizar estado con el nuevo valor
        updateCellState(col, row, newValue);

        // 4. Guardar y Renderizar: Solo si hay un cambio significativo (aunque render() lo manejará)
        guardar();
        render();
    };


    // Escuchamos en el contenedor principal para que los eventos de las celdas internas burbujeen hasta aquí.
    cellGrid.addEventListener('focusout', handleCellEditEnd);
    cellGrid.addEventListener('keydown', (event) => {
        // Solo procesar Enter si se está dentro de una celda editable
        if (event.target && event.target.classList.contains('editable')) {
            handleCellEditEnd(event);
        }
    });

    /** 
     * Maneja el clic derecho para abrir el menú contextual de acciones en la celda.
     * @param {Event} e - El evento de contexto del ratón.
     */
    const handleContextMenu = function(e) {
        // Prevenir el menú nativo del navegador
        e.preventDefault();

        const targetCell = e.target;
        if (!targetCell || !targetCell.classList.contains('editable')) return;

        // Crear y mostrar un menú temporal (simplificado para este entorno)
        let menuId = 'context-menu';
        let menu = document.getElementById(menuId);
        if (!menu) {
            menu = document.createElement('div');
            menu.id = menuId;
            Object.assign(menu.innerHTML, `
                <button class="menu-item" data-action="clear">🗑️ Borrar contenido</button>
                <hr style="margin: 5px;">
                <button class="menu-item color-picker-trigger" data-action="color">🎨 Cambiar fondo</button>
            `);
            document.body.appendChild(menu);
        }

        // Posicionar el menú en la posición del clic derecho
        menu.style.display = 'block';
        menu.style.left = `${e.clientX}px`;
        menu.style.top = `${e.clientY}px`;
    };

    // Listener para abrir el menú al hacer clic derecho
    cellGrid.addEventListener('contextmenu', handleContextMenu);

    // Listener global para cerrar y manejar clics en el menú contextual
    document.addEventListener('click', (e) => {
        const menu = document.getElementById('context-menu');
        if (menu && !menu.contains(e.target) && e.target !== cellGrid) {
            menu.style.display = 'none';
        }
    });

    // Manejo de la selección del color desde el menú contextual
    document.getElementById('context-menu')?.addEventListener('click', (e) => {
        const actionButton = e.target.closest('.menu-item');
        if (!actionButton) return;

        const targetCell = actionButton.dataset.cellTarget; // Asumimos que lo pasamos si es necesario, pero usaremos el foco actual
        let currentElement = document.querySelector('[data-col]:focus') || document.querySelector('.editable:hover');

        if (!currentElement) {
             // Si no hay un elemento visible o enfocado, intentar obtenerlo del último interactuado (simplificación)
             // Para este ejercicio, asumiremos que el clic derecho ocurre sobre la celda activa/objetivo de acción.
             const target = e.target; 
             if (!target || !target.classList.contains('editable')) return;
             currentElement = target;
        }


        const { col, row } = getCoordsFromElement(currentElement);
        const action = actionButton.dataset.action;

        if (action === 'clear') {
            // Borrar contenido
            updateCellState(col, row, "");
        } else if (action === 'color') {
            // Mostrar el selector de color en un input/modal (Aquí lo simplificamos llamando a una función que abre el picker)
             const colorPicker = document.createElement('input');
             colorPicker.type = 'color';
             colorPicker.value = estado[`${col}${row}` + "_bg_color"] || '#ffffff';

             const container = document.getElementById('context-menu');
             if (container) {
                // Reemplazar el botón de color por el picker visible temporalmente
                container.querySelector('[data-action="color"]').style.display = 'none'; 
                Object.assign(container.innerHTML, `<label style="display: block; margin: 5px;">Color:</label><input type="color" id="temp-color-picker" value="${estado[`${col}${row}` + "_bg_color"] || '#ffffff'}">`);

                document.getElementById('temp-color-picker').addEventListener('change', (e) => {
                    const selectedColor = e.target.value;
                    setColor(col, row, selectedColor);
                    // Restaurar el menú después de usarlo
                    setTimeout(() => { 
                         menu.innerHTML = `
                            <button class="menu-item" data-action="clear">🗑️ Borrar contenido</button>
                            <hr style="margin: 5px;">
                            <button class="menu-item color-picker-trigger" data-action="color">🎨 Cambiar fondo</button>
                         `;
                    }, 10);

                });
             }


        }
    });

    // Listener para cerrar el menú al hacer click en cualquier parte fuera de él
     document.addEventListener('click', (e) => {
        const menu = document.getElementById('context-menu');
        if (menu && !menu.contains(e.target)) {
             menu.style.display = 'none';
        }
    });


    /** 
     * Inicializa la aplicación: carga el estado, rellena el estado interno y renderiza la vista inicial.
     */
    // La ejecución de esta función será manejada por el harness después de las definiciones.
    function initializeApp() {
        initializeState(); // Asegura que todos los datos existan en el estado antes de cargar/renderizar
        cargar(); 
        render();
    }
}
