```js
function selectColumn(columnLetter) {
    const controlsContainer = document.getElementById('column-controls');
    if (!controlsContainer) return;

    // 1. Limpiar y mostrar los controles para la nueva columna
    let htmlContent = `
        <div style="margin-bottom: 10px;">
            <strong>Columnas ${columnLetter}:</strong>
            <button id="deleteColumnButton" class="action-btn">🗑️ Borrar Columna</button>
        </div>
        <div style="margin-bottom: 10px;">
            <strong>Acciones de la columna:</strong>
            <button id="clearContentButton" class="action-btn">🧹 Vaciar Contenido</button>
            <button id="colorColumnButton" class="action-btn">🎨 Color Fondo</button>
        </div>
    `;
    controlsContainer.innerHTML = htmlContent;
    controlsContainer.style.display = 'block';

    // 2. Asignar listeners a los nuevos controles
    document.getElementById('deleteColumnButton').addEventListener('click', () => deleteColumn(columnLetter));
    document.getElementById('clearContentButton').addEventListener('click', () => clearColumnContent(columnLetter));
    document.getElementById('colorColumnButton').addEventListener('click', () => showColorPickerForColumn(columnLetter));

    // 3. Actualizar la selección visual de celdas (opcional, pero útil)
    const firstCell = document.querySelector(`.cell[data-col="${columnLetter}"][data-row="1"]`);
    if (firstCell && !document.querySelector('.cell.selected')) {
        handleCellSelection(firstCell);
    } else if (!firstCell){
         // Si la columna no tiene celdas visibles por alguna razón, limpiar selección visual
         document.querySelectorAll('.cell').forEach(c => c.classList.remove('selected'));
    }
}

/** 
 * Oculta los controles de columna y limpia cualquier estado asociado a la columna seleccionada.
 */
function deselectColumn() {
    const controlsContainer = document.getElementById('column-controls');
    if (controlsContainer) {
        controlsContainer.innerHTML = '';
        controlsContainer.style.display = 'none';
    }
    // Limpiar visualmente la selección de celdas
    document.querySelectorAll('.cell').forEach(c => c.classList.remove('selected'));
}

/** 
 * Borra completamente todos los datos y colores asociados a una columna.
 * @param {string} columnLetter - Letra de la columna (A-J).
 */
function deleteColumn(columnLetter) {
    if (!confirm(`¿Está seguro que desea borrar permanentemente toda la columna ${columnLetter}? Esta acción no se puede deshacer.`)) {
        return;
    }

    const keysToDelete = [];
    for (let r = 1; r <= 20; r++) {
        keysToDelete.push(`${columnLetter}${r}`);
    }

    // Limpiar estado de contenido y colores
    keysToDelete.forEach(key => {
        delete estado[key];
        if (window._estadoColores) {
            delete window._estadoColores[key];
        }
    });

    // Guardar, renderizar y limpiar controles
    guardar();
    render();
    deselectColumn();
}

/** 
 * Vacía el contenido de todas las celdas en una columna.
 * @param {string} columnLetter - Letra de la columna (A-J).
 */
function clearColumnContent(columnLetter) {
    const rows = Array.from({ length: 20 }, (_, i) => i + 1);
    let changed = false;

    rows.forEach(row => {
        const key = `${columnLetter}${row}`;
        if (estado[key] !== "") {
            updateCellState(columnLetter, row, "");
            changed = true;
        }
    });

    if (changed) {
        guardar();
        render();
    }
}

/** 
 * Muestra el selector de color para aplicar un fondo a toda la columna.
 * @param {string} columnLetter - Letra de la columna (A-J).
 */
function showColorPickerForColumn(columnLetter) {
    const controlsContainer = document.getElementById('column-controls');
    if (!controlsContainer) return;

    // 1. Reemplazar el botón Color por el picker
    let htmlContent = `
        <div style="margin-bottom: 20px;">
            <strong>Color de Fondo para la columna ${columnLetter}:</strong>
            <input type="color" id="columnColorPickerInput" class="color-picker" style="margin-top: 10px; display: block;">
        </div>
    `;
    controlsContainer.innerHTML = htmlContent;

    const picker = document.getElementById('columnColorPickerInput');
    // Establecer un color por defecto (ej: blanco) o el color actual si existe en la primera celda
    picker.value = '#ffffff'; 

    // 2. Configurar el listener para aplicar el color a toda la columna
    const handleColumnColorChange = (e) => {
        const newColor = e.target.value;
        let changedCount = 0;
        const rows = Array.from({ length: 20 }, (_, i) => i + 1);

        rows.forEach(row => {
            const key = `${columnLetter}${row}`;
            if (window._estadoColores[key] !== newColor) {
                // Actualizar el estado de color para cada celda
                setColorCell(columnLetter, row, newColor); 
                changedCount++;
            }
        });

        if (changedCount > 0) {
             guardar();
             render();
        }
    };

    picker.addEventListener('input', handleColumnColorChange);
}


// Modificar el listener de col-letter en conectar() para manejar la selección y los controles.
